function summarizeServiceOrders(orders, observedMinute) {
  if (!Array.isArray(orders)) throw new TypeError('orders must be an array');
  if (!Number.isSafeInteger(observedMinute) || observedMinute < 0) {
    throw new TypeError('observedMinute must be a non-negative safe integer');
  }
  const statuses = new Set(['pending', 'approved', 'active', 'completed', 'rejected']);
  const actions = {
    pending: ['approve', 'reject', 'edit'],
    approved: ['start', 'edit'],
    active: ['complete'],
    completed: [],
    rejected: []
  };

  return orders.map(order => {
    if (!order || typeof order !== 'object' || typeof order.id !== 'string' || order.id.length === 0 ||
        !statuses.has(order.status) || !Number.isSafeInteger(order.rateCentsPerMinute) ||
        order.rateCentsPerMinute < 0) {
      throw new TypeError('invalid order');
    }
    let durationMinutes = null;
    let totalCents = null;
    if (order.status === 'active') {
      if (!Number.isSafeInteger(order.startMinute) || order.startMinute < 0 || order.startMinute > observedMinute) {
        throw new TypeError('invalid active order time');
      }
      durationMinutes = observedMinute - order.startMinute;
    } else if (order.status === 'completed') {
      if (!Number.isSafeInteger(order.startMinute) || !Number.isSafeInteger(order.endMinute) ||
          order.startMinute < 0 || order.endMinute < order.startMinute) {
        throw new TypeError('invalid completed order time');
      }
      durationMinutes = order.endMinute - order.startMinute;
      totalCents = (durationMinutes + 1) * order.rateCentsPerMinute;
    }
    if ((durationMinutes !== null && !Number.isSafeInteger(durationMinutes)) ||
        (totalCents !== null && !Number.isSafeInteger(totalCents))) {
      throw new RangeError('computed value is not a safe integer');
    }
    return { id: order.id, status: order.status, durationMinutes, totalCents, actions: actions[order.status].slice() };
  });
}

module.exports = { summarizeServiceOrders };

