'use strict';
const assert = require('node:assert/strict');
const api = require('./solution');
assert.deepEqual(Object.keys(api), ['summarizeServiceOrders']);
const { summarizeServiceOrders } = api;

assert.deepEqual(summarizeServiceOrders([], 0), []);
const orders = Object.freeze([
  Object.freeze({ id: 'p', rateCentsPerMinute: 5, status: 'pending' }),
  Object.freeze({ id: 'a', rateCentsPerMinute: 7, status: 'approved' }),
  Object.freeze({ id: 'live', rateCentsPerMinute: 9, status: 'active', startMinute: 10 }),
  Object.freeze({ id: 'done', rateCentsPerMinute: 4, status: 'completed', startMinute: 3, endMinute: 8 }),
  Object.freeze({ id: 'done', rateCentsPerMinute: 2, status: 'completed', startMinute: 5, endMinute: 5 }),
  Object.freeze({ id: 'r', rateCentsPerMinute: 1, status: 'rejected' })
]);
const result = summarizeServiceOrders(orders, 10);
assert.deepEqual(result, [
  { id: 'p', status: 'pending', durationMinutes: null, totalCents: null, actions: ['approve', 'reject', 'edit'] },
  { id: 'a', status: 'approved', durationMinutes: null, totalCents: null, actions: ['start', 'edit'] },
  { id: 'live', status: 'active', durationMinutes: 0, totalCents: null, actions: ['complete'] },
  { id: 'done', status: 'completed', durationMinutes: 5, totalCents: 20, actions: [] },
  { id: 'done', status: 'completed', durationMinutes: 0, totalCents: 0, actions: [] },
  { id: 'r', status: 'rejected', durationMinutes: null, totalCents: null, actions: [] }
]);
assert.notStrictEqual(result[0], result[1]);
assert.notStrictEqual(result[3].actions, result[4].actions);
assert.notStrictEqual(result, orders);

for (const minute of [-1, 1.5, NaN, Infinity, Number.MAX_SAFE_INTEGER + 1]) {
  assert.throws(() => summarizeServiceOrders([], minute), TypeError);
}
assert.throws(() => summarizeServiceOrders({}, 0), TypeError);
const invalidOrders = [
  null,
  { id: '', rateCentsPerMinute: 1, status: 'pending' },
  { id: 'x', rateCentsPerMinute: -1, status: 'pending' },
  { id: 'x', rateCentsPerMinute: 1.5, status: 'pending' },
  { id: 'x', rateCentsPerMinute: 1, status: 'other' },
  { id: 'x', rateCentsPerMinute: 1, status: 'active', startMinute: 2 },
  { id: 'x', rateCentsPerMinute: 1, status: 'active', startMinute: -1 },
  { id: 'x', rateCentsPerMinute: 1, status: 'completed', startMinute: 2, endMinute: 1 },
  { id: 'x', rateCentsPerMinute: 1, status: 'completed', startMinute: 0.5, endMinute: 1 }
];
for (const order of invalidOrders) {
  assert.throws(() => summarizeServiceOrders([order], 1), TypeError);
}
assert.throws(() => summarizeServiceOrders([
  { id: 'overflow', rateCentsPerMinute: Number.MAX_SAFE_INTEGER, status: 'completed', startMinute: 0, endMinute: 2 }
], 0), RangeError);

